 {'kind':'bounded_AST_and_schema_controls','artifacts':[P+'_probes.py',P+'_probes.json',P+'_extra_probes.py',P+'_extra_probes.json'],'controls':10,'runtime':platform.python_version(),'scope':'Vetted function/class fragments with fake I/O plus JSON Schema only; no imports of production initializers, provider/native/subprocess execution or original writes.'},
 {'kind':'whole_population_structured_checks','artifacts':[P+'_population.py',P+'_population.json',P+'_population_extra.py',P+'_population_extra.json'],'scope':'All rows/nested pins/range shapes and selected cross-document counts;270 StageA summary count comparisons,1600 call/trace joins and10 census comparisons. Not full human semantics or fresh historical execution.'},
